//! HTML pages of the `events` resource, generated by
//! `forge generate scaffold`: index, show, new/create, edit/update and
//! delete. Handlers stay thin: authorize, decode the form, call
//! [`EventService`], then render a view or redirect.
//!
//! | Method | Path | Action | Permission |
//! | --- | --- | --- | --- |
//! | `GET` | `/tenants/{tenant_id}/events` | index | `events:read` |
//! | `GET` | `/tenants/{tenant_id}/events/new` | new | `events:write` |
//! | `POST` | `/tenants/{tenant_id}/events` | create | `events:write` |
//! | `GET` | `/tenants/{tenant_id}/events/{id}` | show | `events:read` |
//! | `GET` | `/tenants/{tenant_id}/events/{id}/edit` | edit | `events:write` |
//! | `PATCH`, `PUT` | `/tenants/{tenant_id}/events/{id}` | update | `events:write` |
//! | `DELETE` | `/tenants/{tenant_id}/events/{id}` | delete | `events:write` |
//!
//! HTML forms send `PATCH` and `DELETE` as `POST` with `_method`; the CSRF
//! layer applies the override after checking the token. Invalid input is
//! shown again with `422`, a stale version with `409`, success redirects
//! with `303` and a flash notice.

use std::future::Future;
use std::sync::Arc;

use forge::ComposeError;
use forge::core::{ErrorCategory, ForgeError, Timestamp, Uuid, Version};
use forge::http::{FormError, Method, Request, Response, Router, StatusCode};
use forge::security::Permission;
use forge::tenancy::TenantContext;
use forge::views::{BASE_FIELD, FieldErrors, Flash, csrf_field, csrf_token, see_other};

use crate::adapters::http::access::{AccessDenied, TenantAccess};
use crate::adapters::http::views::Site;
use crate::adapters::http::views::events::{
    EventEdit, EventFormValues, EventIndex, EventNew, EventNotFound, EventRow, EventShow,
};
use crate::application::use_cases::events::{
    EventError, EventService, READ_PERMISSION, WRITE_PERMISSION,
};
use crate::domain::entities::event::{Event, EventAttributes, EventId, EventValidationErrors};

const STALE_UPDATE: &str = "This event was changed by someone else after you opened the form. \
     Review your changes and save again to overwrite.";
const STALE_DELETE: &str = "This event was changed by someone else. Review it and delete it again.";

/// What every event handler shares.
struct EventRoutes {
    site: Arc<Site>,
    service: EventService,
    access: Arc<dyn TenantAccess>,
    read: Permission,
    write: Permission,
}

/// Registers the event routes. `access` decides who may call them (see
/// `crate::adapters::http::access`); nothing is served before it agrees.
pub fn routes(
    router: &mut Router,
    site: &Arc<Site>,
    service: EventService,
    access: Arc<dyn TenantAccess>,
) -> Result<(), ComposeError> {
    let state = Arc::new(EventRoutes {
        site: Arc::clone(site),
        service,
        access,
        read: Permission::new(READ_PERMISSION).map_err(ComposeError::other)?,
        write: Permission::new(WRITE_PERMISSION).map_err(ComposeError::other)?,
    });
    let collection = "/tenants/{tenant_id}/events";
    let member = "/tenants/{tenant_id}/events/{id}";
    route(router, &state, Method::GET, collection, index)?;
    route(
        router,
        &state,
        Method::GET,
        &format!("{collection}/new"),
        new,
    )?;
    route(router, &state, Method::POST, collection, create)?;
    route(router, &state, Method::GET, member, show)?;
    route(router, &state, Method::GET, &format!("{member}/edit"), edit)?;
    route(router, &state, Method::PATCH, member, update)?;
    route(router, &state, Method::PUT, member, update)?;
    route(router, &state, Method::DELETE, member, destroy)?;
    Ok(())
}

fn route<H, F>(
    router: &mut Router,
    state: &Arc<EventRoutes>,
    method: Method,
    path: &str,
    handler: H,
) -> Result<(), ComposeError>
where
    H: Fn(Arc<EventRoutes>, Request) -> F + Send + Sync + 'static,
    F: Future<Output = Response> + Send + 'static,
{
    let state = Arc::clone(state);
    router.route(method, path, move |request: Request| {
        handler(Arc::clone(&state), request)
    })?;
    Ok(())
}

/// Query of the index page: the cursor of the page to show.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct IndexQuery {
    after: Option<EventId>,
}

/// The submitted event form. Fields that must parse are kept as text, so
/// a value that does not parse can be shown again next to its error.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct EventForm {
    #[serde(default)]
    name: String,
    #[serde(default)]
    notes: String,
    #[serde(default)]
    starts_at: String,
    #[serde(default)]
    ends_at: String,
    #[serde(default)]
    capacity: String,
    #[serde(default)]
    attendees: String,
    #[serde(default)]
    public: bool,
    #[serde(default)]
    featured: String,
    #[serde(default)]
    venue: String,
    #[serde(default)]
    organizer: String,
    /// The version the edit form was rendered with.
    #[serde(default)]
    version: Option<i64>,
}

/// The stored event an edit form changes, at the version it expects.
#[derive(Clone, Copy)]
struct EditTarget {
    id: EventId,
    expected: Version,
}

/// The delete form of the show page.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct DeleteForm {
    version: i64,
}

async fn index(state: Arc<EventRoutes>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.read).await {
        Ok(context) => context,
        Err(denied) => return denied.response(),
    };
    let collection = collection_path(&context);
    let Ok(query) = request.query::<IndexQuery>() else {
        return not_found(&state, &request, &collection);
    };
    match state.service.list(&context, query.after).await {
        Ok(page) => forge::web::html(&EventIndex {
            layout: state.site.layout(&request, "Events"),
            new_path: format!("{collection}/new"),
            rows: page
                .events
                .iter()
                .map(|event| row(&collection, event))
                .collect(),
            next_path: page.next.map(|next| format!("{collection}?after={next}")),
        }),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn show(state: Arc<EventRoutes>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.read).await {
        Ok(context) => context,
        Err(denied) => return denied.response(),
    };
    let collection = collection_path(&context);
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    match state.service.find(&context, id).await {
        Ok(event) => forge::web::html(&EventShow {
            layout: state.site.layout(&request, "Event"),
            csrf_field: csrf_field_for(&request),
            back_path: collection.clone(),
            version: event.version().get(),
            event: row(&collection, &event),
        }),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn new(state: Arc<EventRoutes>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return denied.response(),
    };
    let collection = collection_path(&context);
    render_new(
        &state,
        &request,
        &collection,
        EventFormValues::default(),
        FieldErrors::new(),
        StatusCode::OK,
    )
}

async fn create(state: Arc<EventRoutes>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return denied.response(),
    };
    let collection = collection_path(&context);
    let form: EventForm = match request.form() {
        Ok(form) => form,
        Err(error) => {
            return render_new(
                &state,
                &request,
                &collection,
                EventFormValues::default(),
                decode_errors(&error),
                StatusCode::UNPROCESSABLE_ENTITY,
            );
        }
    };
    let values = form.values();
    let attributes = match form.attributes() {
        Ok(attributes) => attributes,
        Err(errors) => {
            return render_new(
                &state,
                &request,
                &collection,
                values,
                errors,
                StatusCode::UNPROCESSABLE_ENTITY,
            );
        }
    };
    match state.service.create(&context, attributes).await {
        Ok(event) => redirect(
            &format!("{collection}/{}", event.id()),
            Flash::new().with_notice("Event was successfully created."),
        ),
        Err(EventError::Invalid(violations)) => render_new(
            &state,
            &request,
            &collection,
            values,
            field_errors(&violations),
            StatusCode::UNPROCESSABLE_ENTITY,
        ),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn edit(state: Arc<EventRoutes>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return denied.response(),
    };
    let collection = collection_path(&context);
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    match state.service.find(&context, id).await {
        Ok(event) => render_edit(
            &state,
            &request,
            &collection,
            &event,
            form_values(&event),
            FieldErrors::new(),
            StatusCode::OK,
        ),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn update(state: Arc<EventRoutes>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return denied.response(),
    };
    let collection = collection_path(&context);
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    // A form that does not decode, or lacks its version, is shown again with
    // the stored values.
    let (form, expected) = match request.form::<EventForm>() {
        Ok(form) => match form.version.map(Version::new) {
            Some(Ok(expected)) => (form, expected),
            _ => {
                let mut errors = FieldErrors::new();
                errors.add(
                    BASE_FIELD,
                    "The form has no valid version; reload the page.",
                );
                return reload_edit(&state, &request, &collection, &context, id, errors).await;
            }
        },
        Err(error) => {
            let errors = decode_errors(&error);
            return reload_edit(&state, &request, &collection, &context, id, errors).await;
        }
    };
    let values = form.values();
    let attributes = match form.attributes() {
        Ok(attributes) => attributes,
        Err(errors) => {
            return render_form_page(
                &state,
                &request,
                &collection,
                EditTarget { id, expected },
                values,
                errors,
                StatusCode::UNPROCESSABLE_ENTITY,
            );
        }
    };
    match state
        .service
        .update(&context, id, expected, attributes)
        .await
    {
        Ok(event) => redirect(
            &format!("{collection}/{}", event.id()),
            Flash::new().with_notice("Event was successfully updated."),
        ),
        Err(EventError::Invalid(violations)) => render_form_page(
            &state,
            &request,
            &collection,
            EditTarget { id, expected },
            values,
            field_errors(&violations),
            StatusCode::UNPROCESSABLE_ENTITY,
        ),
        Err(EventError::Conflict) => {
            // Keep the submitted values and carry the current version, so
            // saving again is a deliberate overwrite.
            match state.service.find(&context, id).await {
                Ok(current) => {
                    let mut errors = FieldErrors::new();
                    errors.add(BASE_FIELD, STALE_UPDATE);
                    let target = EditTarget {
                        id,
                        expected: current.version(),
                    };
                    render_form_page(
                        &state,
                        &request,
                        &collection,
                        target,
                        values,
                        errors,
                        StatusCode::CONFLICT,
                    )
                }
                Err(error) => failure(&state, &request, &collection, error),
            }
        }
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn destroy(state: Arc<EventRoutes>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return denied.response(),
    };
    let collection = collection_path(&context);
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    let member = format!("{collection}/{id}");
    let expected = request
        .form::<DeleteForm>()
        .ok()
        .and_then(|form| Version::new(form.version).ok());
    let Some(expected) = expected else {
        let alert = "The delete form has no valid version; reload the page.";
        return redirect(&member, Flash::new().with_alert(alert));
    };
    match state.service.delete(&context, id, expected).await {
        Ok(()) => redirect(
            &collection,
            Flash::new().with_notice("Event was successfully deleted."),
        ),
        Err(EventError::Conflict) => redirect(&member, Flash::new().with_alert(STALE_DELETE)),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

impl EventForm {
    fn values(&self) -> EventFormValues {
        EventFormValues {
            name: self.name.clone(),
            notes: self.notes.clone(),
            starts_at: self.starts_at.clone(),
            ends_at: self.ends_at.clone(),
            capacity: self.capacity.clone(),
            attendees: self.attendees.clone(),
            public: self.public,
            featured: self.featured.clone(),
            venue: self.venue.clone(),
            organizer: self.organizer.clone(),
        }
    }

    /// Parses the text fields. When one does not parse, the error reports it
    /// together with the business-rule violations of the other fields.
    fn attributes(&self) -> Result<EventAttributes, FieldErrors> {
        let mut errors = FieldErrors::new();
        let attributes = EventAttributes {
            name: self.name.clone(),
            notes: optional_text(&self.notes),
            starts_at: timestamp(&mut errors, "starts_at", &self.starts_at)
                .unwrap_or(Timestamp::UNIX_EPOCH),
            ends_at: optional(&mut errors, "ends_at", &self.ends_at, timestamp),
            capacity: integer(&mut errors, "capacity", &self.capacity).unwrap_or_default(),
            attendees: optional(&mut errors, "attendees", &self.attendees, integer),
            public: self.public,
            featured: optional_boolean(&mut errors, "featured", &self.featured),
            venue: uuid(&mut errors, "venue", &self.venue).unwrap_or_default(),
            organizer: optional(&mut errors, "organizer", &self.organizer, uuid),
        };
        if errors.is_empty() {
            return Ok(attributes);
        }
        if let Err(violations) = attributes.validate() {
            for (field, violation) in violations.iter() {
                if errors.get(field.name()).is_none() {
                    errors.add(field.name(), violation.to_string());
                }
            }
        }
        Err(errors)
    }
}

/// The form values of a stored event.
fn form_values(event: &Event) -> EventFormValues {
    EventFormValues {
        name: event.name().to_owned(),
        notes: event.notes().unwrap_or_default().to_owned(),
        starts_at: event.starts_at().to_datetime_local(),
        ends_at: event
            .ends_at()
            .map(Timestamp::to_datetime_local)
            .unwrap_or_default(),
        capacity: event.capacity().to_string(),
        attendees: event
            .attendees()
            .map(|value| value.to_string())
            .unwrap_or_default(),
        public: event.public(),
        featured: event
            .featured()
            .map(|value| value.to_string())
            .unwrap_or_default(),
        venue: event.venue().to_string(),
        organizer: event
            .organizer()
            .map(|value| value.to_string())
            .unwrap_or_default(),
    }
}

/// A event as display text.
fn row(collection: &str, event: &Event) -> EventRow {
    let show_path = format!("{collection}/{}", event.id());
    EventRow {
        edit_path: format!("{show_path}/edit"),
        show_path,
        name: event.name().to_owned(),
        notes: event.notes().unwrap_or_default().to_owned(),
        starts_at: event.starts_at().to_string(),
        ends_at: event
            .ends_at()
            .map(|value| value.to_string())
            .unwrap_or_default(),
        capacity: event.capacity().to_string(),
        attendees: event
            .attendees()
            .map(|value| value.to_string())
            .unwrap_or_default(),
        public: yes_no(event.public()),
        featured: event.featured().map(yes_no).unwrap_or_default(),
        venue: event.venue().to_string(),
        organizer: event
            .organizer()
            .map(|value| value.to_string())
            .unwrap_or_default(),
    }
}

fn render_new(
    state: &EventRoutes,
    request: &Request,
    collection: &str,
    form: EventFormValues,
    errors: FieldErrors,
    status: StatusCode,
) -> Response {
    forge::web::html_with_status(
        status,
        &EventNew {
            layout: state.site.layout(request, "New event"),
            csrf_field: csrf_field_for(request),
            action: collection.to_owned(),
            method: None,
            version: None,
            submit: "Create event",
            back_path: collection.to_owned(),
            form,
            errors,
        },
    )
}

fn render_edit(
    state: &EventRoutes,
    request: &Request,
    collection: &str,
    event: &Event,
    form: EventFormValues,
    errors: FieldErrors,
    status: StatusCode,
) -> Response {
    let target = EditTarget {
        id: event.id(),
        expected: event.version(),
    };
    render_form_page(state, request, collection, target, form, errors, status)
}

fn render_form_page(
    state: &EventRoutes,
    request: &Request,
    collection: &str,
    target: EditTarget,
    form: EventFormValues,
    errors: FieldErrors,
    status: StatusCode,
) -> Response {
    let show_path = format!("{collection}/{}", target.id);
    forge::web::html_with_status(
        status,
        &EventEdit {
            layout: state.site.layout(request, "Editing event"),
            csrf_field: csrf_field_for(request),
            action: show_path.clone(),
            method: Some("patch"),
            version: Some(target.expected.get()),
            submit: "Update event",
            back_path: collection.to_owned(),
            show_path,
            form,
            errors,
        },
    )
}

/// Shows the edit form again with the stored values and `errors`.
async fn reload_edit(
    state: &EventRoutes,
    request: &Request,
    collection: &str,
    context: &TenantContext,
    id: EventId,
    errors: FieldErrors,
) -> Response {
    match state.service.find(context, id).await {
        Ok(event) => render_edit(
            state,
            request,
            collection,
            &event,
            form_values(&event),
            errors,
            StatusCode::UNPROCESSABLE_ENTITY,
        ),
        Err(error) => failure(state, request, collection, error),
    }
}

fn not_found(state: &EventRoutes, request: &Request, collection: &str) -> Response {
    forge::web::html_with_status(
        StatusCode::NOT_FOUND,
        &EventNotFound {
            layout: state.site.layout(request, "Event not found"),
            back_path: collection.to_owned(),
        },
    )
}

/// Maps a use-case failure that the handler does not render itself.
fn failure(
    state: &EventRoutes,
    request: &Request,
    collection: &str,
    error: EventError,
) -> Response {
    match error {
        EventError::NotFound => not_found(state, request, collection),
        EventError::Invalid(_) => {
            Response::new(StatusCode::UNPROCESSABLE_ENTITY, "unprocessable entity")
        }
        EventError::Conflict => Response::new(StatusCode::CONFLICT, "conflict"),
        EventError::Forbidden => AccessDenied::Forbidden.response(),
        // Logged with its cause chain; the client sees a generic report.
        EventError::Store(error) => forge::web::error(
            &ForgeError::new(
                ErrorCategory::Infrastructure,
                "event_storage_failed",
                "service temporarily unavailable",
            )
            .with_source(error),
        ),
    }
}

/// A body that does not decode was not sent by the generated form; its
/// caller-safe reason is shown above the form.
fn decode_errors(error: &FormError) -> FieldErrors {
    let mut errors = FieldErrors::new();
    errors.add(BASE_FIELD, error.kind().message());
    errors
}

fn field_errors(violations: &EventValidationErrors) -> FieldErrors {
    let mut errors = FieldErrors::new();
    for (field, violation) in violations.iter() {
        errors.add(field.name(), violation.to_string());
    }
    errors
}

/// A `303 See Other` that carries `flash` to the next page.
fn redirect(location: &str, flash: Flash) -> Response {
    let Ok(mut response) = see_other(location) else {
        return Response::empty(StatusCode::INTERNAL_SERVER_ERROR);
    };
    if flash.set_on(&mut response).is_err() {
        return Response::empty(StatusCode::INTERNAL_SERVER_ERROR);
    }
    response
}

fn csrf_field_for(request: &Request) -> String {
    csrf_token(request)
        .map(|token| csrf_field(&token))
        .unwrap_or_default()
}

/// The `{id}` of the route; a value that is not a UUIDv7 is "not found".
fn path_id(request: &Request) -> Option<EventId> {
    request.path_param_as("id").ok()
}

/// `/tenants/<tenant id>/events` of the authorized tenant (never the
/// raw path, which only selected the membership to check).
fn collection_path(context: &TenantContext) -> String {
    format!("/tenants/{}/events", context.tenant_id())
}

fn yes_no(value: bool) -> String {
    if value { "Yes" } else { "No" }.to_owned()
}

/// A blank optional text is no value.
fn optional_text(value: &str) -> Option<String> {
    if value.trim().is_empty() {
        None
    } else {
        Some(value.to_owned())
    }
}

/// The select of an optional checkbox: blank, `true` or `false`.
fn optional_boolean(errors: &mut FieldErrors, field: &str, value: &str) -> Option<bool> {
    match value {
        "" => None,
        "true" => Some(true),
        "false" => Some(false),
        _ => {
            errors.add(field, "must be yes, no or blank");
            None
        }
    }
}

/// A blank optional value is no value; anything else must parse.
fn optional<T>(
    errors: &mut FieldErrors,
    field: &str,
    value: &str,
    parse: fn(&mut FieldErrors, &str, &str) -> Option<T>,
) -> Option<T> {
    if value.trim().is_empty() {
        None
    } else {
        parse(errors, field, value)
    }
}

fn integer(errors: &mut FieldErrors, field: &str, value: &str) -> Option<i64> {
    if value.trim().is_empty() {
        errors.add(field, "can't be blank");
        return None;
    }
    let parsed = value.trim().parse().ok();
    if parsed.is_none() {
        errors.add(field, "must be a whole number");
    }
    parsed
}

fn timestamp(errors: &mut FieldErrors, field: &str, value: &str) -> Option<Timestamp> {
    if value.trim().is_empty() {
        errors.add(field, "can't be blank");
        return None;
    }
    let parsed = Timestamp::parse(value.trim()).ok();
    if parsed.is_none() {
        errors.add(field, "must be a date and time (UTC)");
    }
    parsed
}

fn uuid(errors: &mut FieldErrors, field: &str, value: &str) -> Option<Uuid> {
    if value.trim().is_empty() {
        errors.add(field, "can't be blank");
        return None;
    }
    let parsed = Uuid::parse_str(value.trim()).ok();
    if parsed.is_none() {
        errors.add(field, "must be a UUID");
    }
    parsed
}
